import React, { useMemo, useState, useEffect } from 'react';
import { AppState, FinancialRecord } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { formatCurrency, formatDate } from '../utils/helpers';
import { Wallet, Plus, Trash2, Edit2, ChevronLeft, ChevronRight, TrendingUp, TrendingDown, IndianRupee, ArrowUpRight, ArrowDownRight } from 'lucide-react';
import { deleteFinancialRecord } from '../services/storageService';

interface FinanceDashboardProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
  onAddTransaction: () => void;
  onEditTransaction: (record: FinancialRecord) => void;
}

const FinanceDashboard: React.FC<FinanceDashboardProps> = ({ state, refreshState, onAddTransaction, onEditTransaction }) => {
  // Default to current month, but allow auto-switching
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM

  // Auto-switch to most recent month with data on load if current month is empty
  useEffect(() => {
    const currentMonth = new Date().toISOString().slice(0, 7);
    const hasCurrentData = state.financialRecords.some(r => r.date.startsWith(currentMonth));

    if (!hasCurrentData && state.financialRecords.length > 0) {
      // Find the latest record
      const sorted = [...state.financialRecords].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      if (sorted[0]) {
        setSelectedMonth(sorted[0].date.slice(0, 7));
      }
    }
  }, [state.financialRecords]);

  // Navigation Handlers
  const handlePrevMonth = () => {
    const d = new Date(selectedMonth + '-01');
    d.setMonth(d.getMonth() - 1);
    setSelectedMonth(d.toISOString().slice(0, 7));
  };

  const handleNextMonth = () => {
    const d = new Date(selectedMonth + '-01');
    d.setMonth(d.getMonth() + 1);
    setSelectedMonth(d.toISOString().slice(0, 7));
  };

  const formatMonthDisplay = (yyyyMm: string) => {
    if (!yyyyMm) return '';
    const d = new Date(yyyyMm + '-01');
    return d.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
  };

  // Process Data for Selected Month
  const monthlyData = useMemo(() => {
    // 1. Get Financial Records (Income & Expense)
    const records = state.financialRecords.filter(r => r.date.startsWith(selectedMonth));

    // 2. Get Maintenance Collections (Treat as Income)
    const collections = state.transactions.filter(t => t.date.startsWith(selectedMonth));
    const maintenanceIncome = collections.reduce((acc, t) => acc + t.amount, 0);

    // 3. Summarize
    const expenses = records.filter(r => r.type === 'EXPENSE').reduce((acc, r) => acc + r.amount, 0);
    const otherIncome = records.filter(r => r.type === 'INCOME').reduce((acc, r) => acc + r.amount, 0);

    const totalIncome = maintenanceIncome + otherIncome;
    const netChange = totalIncome - expenses;

    // 4. Combine List for Display
    const combinedList = [
      ...records,
    ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    return {
      maintenanceIncome,
      otherIncome,
      totalIncome,
      expenses,
      netChange,
      records: combinedList
    };
  }, [state.financialRecords, state.transactions, selectedMonth]);

  // Available Balance (Lifetime)
  const availableBalance = useMemo(() => {
    const totalMaintenance = state.transactions.reduce((acc, t) => acc + t.amount, 0);
    const totalOtherIncome = state.financialRecords.filter(r => r.type === 'INCOME').reduce((acc, r) => acc + r.amount, 0);
    const totalExpense = state.financialRecords.filter(r => r.type === 'EXPENSE').reduce((acc, r) => acc + r.amount, 0);
    return (totalMaintenance + totalOtherIncome) - totalExpense;
  }, [state.transactions, state.financialRecords]);

  // Chart Data
  const chartData = [
    { name: 'Income', value: monthlyData.totalIncome, fill: '#10b981' }, // Emerald-500
    { name: 'Expense', value: monthlyData.expenses, fill: '#f43f5e' }, // Rose-500
  ];

  // Expense Breakdown Pie Data
  const expenseBreakdown = useMemo(() => {
     const catMap = new Map<string, number>();
     state.financialRecords
       .filter(r => r.date.startsWith(selectedMonth) && r.type === 'EXPENSE')
       .forEach(r => {
          const cat = r.category || 'Uncategorized';
          catMap.set(cat, (catMap.get(cat) || 0) + r.amount);
       });

     return Array.from(catMap.entries()).map(([name, value]) => ({ name, value }));
  }, [state.financialRecords, selectedMonth]);

  const PIE_COLORS = ['#3b82f6', '#f59e0b', '#10b981', '#ef4444', '#8b5cf6', '#ec4899'];

  const handleDelete = (record: FinancialRecord) => {
    if(window.confirm(`Delete record: "${record.description || record.category}" (${formatCurrency(record.amount)})?`)) {
      const newState = deleteFinancialRecord(state, record.id);
      refreshState(newState);
    }
  };

  return (
    <div className="p-4 space-y-6 pb-24">
      {/* Date Navigation Header - Sticky */}
      <div className="sticky top-0 z-20 bg-white border-b border-slate-200 shadow-sm px-4 py-3 flex items-center justify-between -mx-4 -mt-4 mb-6">
        <button 
          onClick={handlePrevMonth}
          className="p-2 rounded-full hover:bg-slate-100 text-slate-600 transition-colors active:bg-slate-200"
        >
          <ChevronLeft size={24} />
        </button>

        <h2 className="text-lg font-bold text-slate-800">
          {formatMonthDisplay(selectedMonth)}
        </h2>

        <button 
          onClick={handleNextMonth}
          className="p-2 rounded-full hover:bg-slate-100 text-slate-600 transition-colors active:bg-slate-200"
        >
          <ChevronRight size={24} />
        </button>
      </div>

      {/* 4-Card Summary Grid (Matching User Screenshot) */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">

          {/* Card 1: Funds Available */}
          <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex flex-col justify-between h-full relative overflow-hidden">
               <div className="flex justify-between items-start mb-4 relative z-10">
                  <div>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">FUNDS AVAILABLE</p>
                      <h3 className="text-2xl font-bold text-slate-800">{formatCurrency(availableBalance)}</h3>
                  </div>
                  <div className="bg-blue-50 p-3 rounded-2xl text-blue-600 shadow-sm">
                      <Wallet size={24} />
                  </div>
               </div>
          </div>

          {/* Card 2: Monthly Income */}
          <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex flex-col justify-between h-full relative overflow-hidden">
               <div className="flex justify-between items-start mb-4 relative z-10">
                  <div>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">MONTHLY INCOME</p>
                      <h3 className="text-2xl font-bold text-emerald-600">{formatCurrency(monthlyData.totalIncome)}</h3>
                  </div>
                  <div className="bg-emerald-50 p-3 rounded-full text-emerald-600 shadow-sm">
                      <TrendingUp size={24} />
                  </div>
               </div>
          </div>

          {/* Card 3: Monthly Expenses */}
          <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex flex-col justify-between h-full relative overflow-hidden">
               <div className="flex justify-between items-start mb-4 relative z-10">
                  <div>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">MONTHLY EXPENSES</p>
                      <h3 className="text-2xl font-bold text-red-600">{formatCurrency(monthlyData.expenses)}</h3>
                  </div>
                  <div className="bg-red-50 p-3 rounded-full text-red-600 shadow-sm">
                      <TrendingDown size={24} />
                  </div>
               </div>
          </div>

           {/* Card 4: Net This Month */}
          <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex flex-col justify-between h-full relative overflow-hidden">
               <div className="flex justify-between items-start mb-4 relative z-10">
                  <div>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">NET THIS MONTH</p>
                      <h3 className={`text-2xl font-bold ${monthlyData.netChange >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>{formatCurrency(monthlyData.netChange)}</h3>
                  </div>
                  <div className={`p-3 rounded-full shadow-sm ${monthlyData.netChange >= 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                      <IndianRupee size={24} />
                  </div>
               </div>
          </div>
      </div>

      {/* Charts Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
           {/* Financial Overview (Bar Chart) */}
           <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-base font-bold text-slate-800">Financial Overview</h3>
                    <span className="text-xs bg-slate-100 px-3 py-1 rounded-full text-slate-500 font-bold">Year to Date</span>
                </div>
                <div className="h-64 w-full">
                     <ResponsiveContainer>
                        <BarChart data={chartData} barSize={40}>
                            <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                            <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} tickFormatter={(val) => val >= 1000 ? `${val/1000}k` : val} />
                            <Tooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 4px 20px rgba(0,0,0,0.05)'}} formatter={(val: number) => formatCurrency(val)} />
                            <Bar dataKey="value" radius={[6, 6, 6, 6]}>
                                {chartData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={entry.fill} />
                                ))}
                            </Bar>
                        </BarChart>
                     </ResponsiveContainer>
                </div>
           </div>

           {/* Expense Breakdown (Donut Chart) */}
           <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
                <h3 className="text-base font-bold text-slate-800 mb-6">Expense Breakdown</h3>
                <div className="h-64 w-full">
                    {expenseBreakdown.length > 0 ? (
                        <ResponsiveContainer>
                            <PieChart>
                                <Pie data={expenseBreakdown} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                                    {expenseBreakdown.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip formatter={(val: number) => formatCurrency(val)} contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 4px 20px rgba(0,0,0,0.05)'}} />
                                <Legend layout="vertical" verticalAlign="middle" align="right" iconType="circle" iconSize={8} wrapperStyle={{fontSize: '12px', color: '#64748b'}} />
                            </PieChart>
                        </ResponsiveContainer>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-slate-400">
                            <p className="text-sm">No expenses recorded</p>
                        </div>
                    )}
                </div>
           </div>
      </div>

      {/* Transaction List */}
      <div>
         <div className="flex justify-between items-center mb-4">
             <h3 className="text-sm font-bold text-slate-700 uppercase">Transactions</h3>
             <span className="text-xs font-medium text-slate-400">{monthlyData.records.length} Records</span>
         </div>

         <div className="space-y-3">
             {/* Maintenance Summary Item */}
             {monthlyData.maintenanceIncome > 0 && (
                 <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm flex justify-between items-center">
                     <div className="flex items-center space-x-3">
                         <div className="bg-green-50 text-green-600 p-2.5 rounded-xl">
                             <Wallet size={20} />
                         </div>
                         <div>
                             <p className="text-sm font-bold text-slate-800">Maintenance Collections</p>
                             <p className="text-xs text-slate-400">Aggregated for {selectedMonth}</p>
                         </div>
                     </div>
                     <span className="font-bold text-green-600">+{formatCurrency(monthlyData.maintenanceIncome)}</span>
                 </div>
             )}

             {monthlyData.records.length > 0 ? monthlyData.records.map(record => (
                 <div key={record.id} className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm flex flex-col gap-3">
                     <div className="flex justify-between items-start">
                         <div className="flex items-center space-x-3">
                             <div className={`p-2.5 rounded-xl ${record.type === 'INCOME' ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'}`}>
                                 {record.type === 'INCOME' ? <ArrowUpRight size={20} /> : <ArrowDownRight size={20} />}
                             </div>
                             <div>
                                 <p className="text-sm font-bold text-slate-800">{record.description || record.category}</p>
                                 <div className="flex items-center space-x-2 text-xs text-slate-500 mt-1">
                                     <span className="bg-slate-50 px-2 py-0.5 rounded border border-slate-100">{record.category}</span>
                                     <span>{formatDate(record.date).replace(/ /g, '-').replace(',', '')}</span>
                                 </div>
                             </div>
                         </div>
                         <div className="text-right">
                            <p className={`font-bold text-base ${record.type === 'INCOME' ? 'text-green-600' : 'text-red-600'}`}>
                               {record.type === 'INCOME' ? '+' : '-'}{formatCurrency(record.amount)}
                            </p>
                         </div>
                     </div>

                     <div className="flex justify-end gap-3 pt-3 border-t border-slate-50">
                        <button 
                            onClick={() => onEditTransaction(record)} 
                            className="flex-1 flex items-center justify-center space-x-1.5 py-2 bg-blue-50 text-blue-600 rounded-lg text-xs font-bold hover:bg-blue-100 transition-colors"
                        >
                            <Edit2 size={14} />
                            <span>Edit</span>
                        </button>
                        <button 
                            onClick={() => handleDelete(record)} 
                            className="flex-1 flex items-center justify-center space-x-1.5 py-2 bg-red-50 text-red-600 rounded-lg text-xs font-bold hover:bg-red-100 transition-colors"
                        >
                            <Trash2 size={14} />
                            <span>Delete</span>
                        </button>
                     </div>
                 </div>
             )) : (
                 monthlyData.maintenanceIncome === 0 && <div className="text-center py-10 text-slate-400 text-sm">No transactions recorded for this month.</div>
             )}
         </div>
      </div>

      {/* Floating Action Button */}
      <button 
        onClick={onAddTransaction}
        className="fixed bottom-24 right-4 bg-blue-600 text-white p-4 rounded-full shadow-lg shadow-blue-300 hover:bg-blue-700 active:scale-95 transition-transform z-20"
      >
        <Plus size={24} />
      </button>

    </div>
  );
};

export default FinanceDashboard;

import React, { useMemo, useState, useEffect } from 'react';
import { AppState, FinancialRecord } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { formatCurrency, formatDate } from '../utils/helpers';
import { Wallet, Plus, Trash2, Edit2, ChevronLeft, ChevronRight, TrendingUp, TrendingDown, IndianRupee, ArrowUpRight, ArrowDownRight } from 'lucide-react';
import { deleteFinancialRecord } from '../services/storageService';

interface FinanceDashboardProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
  onAddTransaction: () => void;
  onEditTransaction: (record: FinancialRecord) => void;
}

const FinanceDashboard: React.FC<FinanceDashboardProps> = ({ state, refreshState, onAddTransaction, onEditTransaction }) => {
  // Default to current month, but allow auto-switching
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM

  // Auto-switch to most recent month with data on load if current month is empty
  useEffect(() => {
    const currentMonth = new Date().toISOString().slice(0, 7);
    const hasCurrentData = state.financialRecords.some(r => r.date.startsWith(currentMonth));

    if (!hasCurrentData && state.financialRecords.length > 0) {
      // Find the latest record
      const sorted = [...state.financialRecords].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      if (sorted[0]) {
        setSelectedMonth(sorted[0].date.slice(0, 7));
      }
    }
  }, [state.financialRecords]);

  // Navigation Handlers
