import React, { useMemo, useState, useEffect } from 'react';
import { AppState, FinancialRecord } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { formatCurrency, formatDate } from '../utils/helpers';
import { Wallet, Plus, Trash2, Edit2, ChevronLeft, ChevronRight, TrendingUp, TrendingDown, IndianRupee, ArrowUpRight, ArrowDownRight, Building2, Sparkles, AlertCircle } from 'lucide-react';
import { deleteFinancialRecord, updateInsight } from '../services/storageService';
import { generateFinancialInsight } from '../services/geminiService';

interface FinanceDashboardProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
  onAddTransaction: () => void;
  onEditTransaction: (record: FinancialRecord) => void;
}

const FinanceDashboard: React.FC<FinanceDashboardProps> = ({ state, refreshState, onAddTransaction, onEditTransaction }) => {
  // Default to current month, but allow auto-switching
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [loadingInsight, setLoadingInsight] = useState(false);

  // Auto-switch to most recent month with data on load if current month is empty
  useEffect(() => {
    const currentMonth = new Date().toISOString().slice(0, 7);
    const hasCurrentData = state.financialRecords.some(r => r.date.startsWith(currentMonth));

    if (!hasCurrentData && state.financialRecords.length > 0) {
      // Find the latest record
      const sorted = [...state.financialRecords].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      if (sorted[0]) {
        setSelectedMonth(sorted[0].date.slice(0, 7));
      }
    }
  }, [state.financialRecords]);

  // Navigation Handlers
  const handlePrevMonth = () => {
    const d = new Date(selectedMonth + '-01');
    d.setMonth(d.getMonth() - 1);
    setSelectedMonth(d.toISOString().slice(0, 7));
  };

  const handleNextMonth = () => {
    const d = new Date(selectedMonth + '-01');
    d.setMonth(d.getMonth() + 1);
    setSelectedMonth(d.toISOString().slice(0, 7));
  };

  const formatMonthDisplay = (yyyyMm: string) => {
    if (!yyyyMm) return '';
    const d = new Date(yyyyMm + '-01');
    return d.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
  };

  // Process Data for Selected Month
  const monthlyData = useMemo(() => {
    const startOfMonth = selectedMonth + '-01';

    // 1. Calculate Opening Balance (Everything strictly before this month)
    // NOTE: Excluding automatic maintenance collections from transactions as per user request.
    // User will manually enter consolidated income.
    /*
    const prevCollections = state.transactions
      .filter(t => t.date < startOfMonth)
      .reduce((acc, t) => acc + t.amount, 0);
    */

    const prevFinancialIncome = state.financialRecords
      .filter(r => r.type === 'INCOME' && r.date < startOfMonth)
      .reduce((acc, r) => acc + r.amount, 0);

    const prevExpenses = state.financialRecords
      .filter(r => r.type === 'EXPENSE' && r.date < startOfMonth)
      .reduce((acc, r) => acc + r.amount, 0);

    const openingBalance = prevFinancialIncome - prevExpenses;

    // 2. Current Month Data
    const records = state.financialRecords.filter(r => r.date.startsWith(selectedMonth));

    // NOTE: Excluding current month collections.
    /*
    const collections = state.transactions.filter(t => t.date.startsWith(selectedMonth));
    const maintenanceIncome = collections.reduce((acc, t) => acc + t.amount, 0);
    */
    const maintenanceIncome = 0;

    const expenses = records.filter(r => r.type === 'EXPENSE').reduce((acc, r) => acc + r.amount, 0);
    const otherIncome = records.filter(r => r.type === 'INCOME').reduce((acc, r) => acc + r.amount, 0);

    const totalIncome = otherIncome; // Was maintenanceIncome + otherIncome
    const netChange = totalIncome - expenses;

    // 3. Closing Balance (End of this month)
    const closingBalance = openingBalance + netChange;

    // 4. Combine List for Display
    const combinedList = [
      ...records,
    ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    return {
      openingBalance,
      closingBalance,
      maintenanceIncome,
      otherIncome,
      totalIncome,
      expenses,
      netChange,
      records: combinedList
    };
  }, [state.financialRecords, selectedMonth]); // Removed state.transactions dependency

  // Chart Data
  const chartData = [
    { name: 'Income', value: monthlyData.totalIncome, fill: '#10b981' }, // Emerald-500
    { name: 'Expense', value: monthlyData.expenses, fill: '#f43f5e' }, // Rose-500
  ];

  // Expense Breakdown Pie Data
  const expenseBreakdown = useMemo(() => {
     const catMap = new Map<string, number>();
     state.financialRecords
       .filter(r => r.date.startsWith(selectedMonth) && r.type === 'EXPENSE')
       .forEach(r => {
          const cat = r.category || 'Uncategorized';
          catMap.set(cat, (catMap.get(cat) || 0) + r.amount);
       });

     return Array.from(catMap.entries()).map(([name, value]) => ({ name, value }));
  }, [state.financialRecords, selectedMonth]);

  const PIE_COLORS = ['#3b82f6', '#f59e0b', '#10b981', '#ef4444', '#8b5cf6', '#ec4899'];

  const handleDelete = (record: FinancialRecord) => {
    if(window.confirm(`Delete record: "${record.description || record.category}" (${formatCurrency(record.amount)})?`)) {
      const newState = deleteFinancialRecord(state, record.id);
      refreshState(newState);
    }
  };

  const handleGenerateInsight = async () => {
      setLoadingInsight(true);
      // We reuse the service but passing current view context would be better.
      // For now, using standard service which analyzes general state.
      // In a real app, we'd pass monthlyData to a specific finance insight function.
      const text = await generateFinancialInsight(state);
      const newState = updateInsight(state, text);
      refreshState(newState);
      setLoadingInsight(false);
  };

  const insight = state.aiInsight?.text;

  return (
    <div className="p-4 space-y-6 pb-24">
      {/* Date Navigation Header - Sticky */}
