                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 truncate">MONTHLY INCOME</p>
                      <h3 className="text-xl font-bold text-emerald-600 truncate" title={formatCurrency(monthlyData.totalIncome)}>{formatCurrency(monthlyData.totalIncome)}</h3>
                  </div>
                  <div className="bg-emerald-50 p-2 rounded-xl text-emerald-600 shadow-sm ml-2 shrink-0 h-fit">
                      <TrendingUp size={16} />
                  </div>
               </div>
          </div>

          {/* Card 3: Monthly Expenses */}
          <div className="min-w-[160px] snap-center bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col justify-between h-28 relative overflow-hidden">
               <div className="flex justify-between items-start mb-2 relative z-10">
                  <div className="flex-1 min-w-0">
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 truncate">MONTHLY EXPENSES</p>
                      <h3 className="text-xl font-bold text-red-600 truncate" title={formatCurrency(monthlyData.expenses)}>{formatCurrency(monthlyData.expenses)}</h3>
                  </div>
                  <div className="bg-red-50 p-2 rounded-xl text-red-600 shadow-sm ml-2 shrink-0 h-fit">
                      <TrendingDown size={16} />
                  </div>
               </div>
          </div>

           {/* Card 4: Net This Month */}
          <div className="min-w-[160px] snap-center bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col justify-between h-28 relative overflow-hidden">
               <div className="flex justify-between items-start mb-2 relative z-10">
                  <div className="flex-1 min-w-0">
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 truncate">NET THIS MONTH</p>
                      <h3 className={`text-xl font-bold ${monthlyData.netChange >= 0 ? 'text-emerald-600' : 'text-red-600'} truncate`} title={formatCurrency(monthlyData.netChange)}>{formatCurrency(monthlyData.netChange)}</h3>
                  </div>
                  <div className={`p-2 rounded-xl shadow-sm ml-2 shrink-0 h-fit ${monthlyData.netChange >= 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                      <IndianRupee size={16} />
                  </div>
               </div>
          </div>
      </div>

      {/* Charts Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
           {/* Financial Overview (Bar Chart) */}
           <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-base font-bold text-slate-800">Financial Overview</h3>
                    <span className="text-xs bg-slate-100 px-3 py-1 rounded-full text-slate-500 font-bold">Year to Date</span>
                </div>
                <div className="h-64 w-full">
                     <ResponsiveContainer>
