export const triggerNativePrint = (elementId: string) => {
  const content = document.getElementById(elementId);
  if (!content) return;

  // Store original body content
  const originalBody = document.body.innerHTML;

  // Replace body with just the content to print
  // We wrap it in a container that handles the layout reset
  document.body.innerHTML = `
    <div style="width: 100%; height: auto; overflow: visible;">
      ${content.innerHTML}
    </div>
  `;

  // Trigger print
  window.print();

  // Restore original content
  window.location.reload();
};

export const downloadPDF = (elementId: string, fileName: string) => {
  const element = document.getElementById(elementId);
  if (!element) return;

  // @ts-ignore
  if (!window.html2pdf) {
    alert("PDF generator is loading. Please try again in 3 seconds.");
    return;
  }

  // 1. Clone the element to avoid manipulating the view for the user
  const clone = element.cloneNode(true) as HTMLElement;

  // 2. Remove 'no-print' elements from the clone
  const noPrints = clone.querySelectorAll('.no-print');
  noPrints.forEach(el => el.remove());

  // 3. Make 'print:block' elements visible in the clone
  // (These are headers usually hidden on screen but needed in PDF)
  const printOnly = clone.querySelectorAll('.hidden.print\\:block');
  printOnly.forEach(el => {
      el.classList.remove('hidden', 'print:block');
      el.classList.add('block');
  });

  // 4. Make 'print:inline' elements visible in the clone
  // (This fixes issues where amounts or other inline text hidden on screen don't show up in PDF)
  const printOnlyInline = clone.querySelectorAll('.hidden.print\\:inline');
  printOnlyInline.forEach(el => {
      el.classList.remove('hidden', 'print:inline');
      el.classList.add('inline');
  });

  // 5. Force styles for the PDF rendering
  clone.style.width = '100%'; 
  clone.style.maxWidth = 'none';
  clone.style.padding = '20px';
  clone.style.background = 'white';
  clone.style.color = 'black';

  // 6. Append clone to a hidden container in body so html2pdf can render it
  const container = document.createElement('div');
  container.style.position = 'absolute';
  container.style.top = '-9999px';
  container.style.left = '0px';
  container.style.width = '800px'; // Fixed width for A4 consistency
  container.appendChild(clone);
  document.body.appendChild(container);

  // 7. Generate PDF
  const opt = {
    margin: [10, 10, 10, 10], // top, left, bottom, right
    filename: fileName,
    image: { type: 'jpeg', quality: 0.98 },
    html2canvas: { scale: 2, useCORS: true, logging: false },
    jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
  };

  // @ts-ignore
  window.html2pdf()
    .set(opt)
    .from(clone)
    .save()
    .then(() => {
        // Cleanup
        document.body.removeChild(container);
    })
    .catch((err: any) => {
        console.error("PDF generation failed", err);
        document.body.removeChild(container);
        alert("Failed to generate PDF. Please check console.");
    });
};

