      downloadPDF('printable-section', fileName);
    } else {
      const fileName = `Unpaid_List_${getTodayDateString()}.pdf`;
      downloadPDF('printable-section', fileName);
    }
  };

  if (view === 'REPORTS') {
    return (
      <div className="p-4" id="printable-section">
        {/* Screen Header */}
        <div className="flex justify-between items-center mb-6 no-print">
          <h2 className="text-xl font-bold text-slate-800">Daily Collection Report</h2>
          <button 
            onClick={handleDownload} 
            className="flex items-center space-x-2 text-white bg-blue-600 px-4 py-2 rounded-lg text-sm font-bold hover:bg-blue-700 shadow-md transition-colors"
          >
            <Download size={16} />
            <span>Save PDF</span>
          </button>
        </div>

        {/* Print Only Header (Hidden normally, visible in PDF) */}
        <div className="hidden print:block text-center mb-6 border-b border-black pb-4">
            <h1 className="text-2xl font-bold text-black mb-1">CONTINENTAL HEIGHTS B WING</h1>
            <h2 className="text-xl font-semibold text-black">DAILY COLLECTION REPORT AS ON {formatDate(selectedDate).toUpperCase()}</h2>
        </div>

        {/* Controls - No Print */}
        <div className="bg-white p-4 rounded-xl border border-slate-200 mb-6 flex justify-start items-center gap-12 shadow-sm no-print">
          <div>
             <label className="text-xs text-slate-500 uppercase font-semibold mb-1 flex items-center">
                <Calendar size={12} className="mr-1" />
                Select Date
             </label>
             <input
                type="date"
                value={selectedDate}
                onChange={(e) => setSelectedDate(e.target.value)}
                className="font-bold text-slate-900 bg-slate-50 border border-slate-200 rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
             />
          </div>
          <div className="text-right">
             <p className="text-xs text-slate-500 uppercase font-semibold mb-1">Total Amount</p>
             <p className="text-xl font-bold text-green-600">{formatCurrency(dailyTotal)}</p>
          </div>
        </div>

        {/* Total for Print */}
        <div className="hidden print:block mb-4 text-right">
             <p className="text-lg font-bold text-black">
               Total Collection: Rs. {dailyTotal.toLocaleString('en-IN')}
             </p>
        </div>

        <h3 className="text-sm font-semibold text-slate-500 uppercase mb-3 no-print">Transactions ({dailyReport.length})</h3>

        {dailyReport.length === 0 ? (
           <div className="text-center py-10 bg-slate-50 rounded-xl border border-dashed border-slate-300">
            <Clock className="mx-auto text-slate-400 mb-2" />
            <p className="text-slate-500">
              {selectedDate ? `No transactions found for ${formatDate(selectedDate)}.` : 'Please select a date.'}
            </p>
           </div>
        ) : (
          <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden print:border-black print:shadow-none">
             {/* Header - Enforce Black BG in Print */}
             <div className="flex items-center bg-black p-3 border-b border-black text-xs font-bold text-white uppercase tracking-wider print:bg-black print:text-white print:border-black">
                <div className="w-12 shrink-0">Rcpt</div>
                <div className="w-16 shrink-0">Flat</div>
                <div className="flex-1 md:flex-none md:w-80 print:flex-none print:w-80 min-w-0 px-2">Owner</div>
                <div className="w-20 shrink-0 text-right">Amount</div>
                <div className="w-14 shrink-0 text-center no-print">Action</div>
             </div>

             {/* Body */}
             <div className="divide-y divide-slate-100 print:divide-black">
                {dailyReport.map((t) => (
                  <div key={t.receiptNo} className="flex items-center p-3 text-xs hover:bg-slate-50 transition-colors print:hover:bg-transparent">
                    <div className="w-12 shrink-0 font-mono text-slate-500 print:text-black">#{t.receiptNo}</div>
                    <div className="w-16 shrink-0 font-bold text-slate-800 print:text-black">{t.flatNumber}</div>
                    <div className="flex-1 md:flex-none md:w-80 print:flex-none print:w-80 min-w-0 px-2 truncate text-slate-600 print:text-black" title={t.ownerName}>
                        {t.ownerName}
                    </div>
                    <div className="w-20 shrink-0 text-right font-medium text-slate-900 print:text-black">
                        {/* Use simple formatting for print to avoid symbol issues */}
                        <span className="no-print">{formatCurrency(t.amount)}</span>
                        <span className="hidden print:inline">{t.amount.toLocaleString('en-IN')}</span>
                    </div>
                    {/* Action Buttons - Hide in Print */}
                    <div className="w-14 shrink-0 flex justify-center space-x-1 no-print">
                        <a 
                             href={generateWhatsAppLink(t.mobile, t.receiptNo, t.ownerName, t.flatNumber, t.amount, formatDate(t.date))}
                             target="_blank"
                             rel="noreferrer"
                             className="text-green-600 p-1.5 hover:bg-green-100 rounded transition-colors"
                             title="Share WhatsApp"
                        >
                            <Share2 size={14} />
                        </a>
                        {onEditTransaction && (
                             <button
                               onClick={() => onEditTransaction(t)}
                               className="text-blue-600 p-1.5 hover:bg-blue-100 rounded transition-colors"
                               title="Edit"
                             >
                                <Edit2 size={14} />
                             </button>
                        )}
                    </div>
                  </div>
                ))}
             </div>
          </div>
        )}
      </div>
    );
  }

  // UNPAID LIST VIEW
  return (
    <div className="p-4 h-full flex flex-col" id="printable-section">
       {/* Screen Header */}
       <div className="flex justify-between items-end mb-6 no-print">
        <div>
            <h2 className="text-xl font-bold text-slate-800">Pending Payments</h2>
            <span className="bg-red-100 text-red-700 px-3 py-1 rounded-full text-xs font-bold mt-2 inline-block">
            {unpaidFlats.length} Pending
            </span>
        </div>
        <button 
            onClick={handleDownload} 
            className="flex items-center space-x-2 text-white bg-blue-600 px-4 py-2 rounded-lg text-sm font-bold hover:bg-blue-700 shadow-md transition-colors"
          >
            <Download size={16} />
            <span>Save PDF</span>
          </button>
       </div>

       {/* Print Only Header */}
       <div className="hidden print:block text-center mb-6 border-b border-black pb-4">
            <h1 className="text-2xl font-bold text-black mb-1">CONTINENTAL HEIGHTS B WING</h1>
            <h2 className="text-xl font-semibold text-black">UNPAID MAINTENANCE LIST AS ON {formatDate(getTodayDateString()).toUpperCase()}</h2>
            <div className="mt-4 flex flex-col items-end">
                <p className="font-bold text-black">Total Pending Flats: {unpaidFlats.length}</p>
                <p className="font-bold text-black">Total Pending Amount: Rs. {(unpaidFlats.length * MAINTENANCE_AMOUNT).toLocaleString('en-IN')}</p>
            </div>
       </div>

       <div className="flex-1 overflow-y-auto bg-white rounded-xl border border-slate-200 shadow-sm print:shadow-none print:border-none print:overflow-visible print:h-auto print:block">
        {/* Header - Enforce Black BG in Print */}
        <div className="flex items-center bg-black p-3 border-b border-black text-xs font-bold text-white uppercase tracking-wider print:bg-black print:text-white print:border-black sticky top-0 z-10">
           <div className="w-16 shrink-0">Flat</div>
           <div className="flex-1 md:flex-none md:w-96 print:flex-none print:w-96 min-w-0 px-2">Owner</div>
           <div className="w-24 shrink-0 text-center">Status</div>
           <div className="w-16 shrink-0 text-center no-print">Remind</div>
        </div>

        {/* Body - Single Line, Compact Flex Layout */}
        <div className="divide-y divide-slate-100 print:divide-black">
          {unpaidFlats.map(flat => (
            <div key={flat.id} className="flex items-center p-2 text-xs hover:bg-slate-50 transition-colors print:hover:bg-transparent">
               {/* Flat Number */}
               <div className="w-16 shrink-0 font-bold text-slate-800 print:text-black">{flat.flatNumber}</div>

               {/* Owner Name - Single Line, Fixed width in Print/Desktop to align columns, fills remaining space on mobile */}
               <div className="flex-1 md:flex-none md:w-96 print:flex-none print:w-96 min-w-0 px-2 truncate text-slate-600 print:text-black" title={flat.ownerName}>
                  {flat.ownerName || '-'}
               </div>

               {/* Status */}
               <div className="w-24 shrink-0 flex items-center justify-center text-red-600 font-bold print:text-black">
                   <AlertCircle size={12} className="mr-1 no-print" />
                   <span>UNPAID</span>
               </div>

               {/* Remind Action */}
               <div className="w-16 shrink-0 flex justify-center no-print">
                   {flat.mobile ? (
                     <a 
                       href={generateReminderLink(flat.mobile, flat.ownerName, flat.flatNumber)}
                       target="_blank"
                       rel="noreferrer"
                       className="text-green-600 p-1.5 hover:bg-green-100 rounded transition-colors"
                       title="Send WhatsApp Reminder"
                     >
                        <MessageCircle size={16} />
                     </a>
                   ) : (
                     <span className="text-slate-300 p-1.5"><MessageCircle size={16} /></span>
                   )}
               </div>
            </div>
          ))}

          {unpaidFlats.length === 0 && (
            <div className="p-8 text-center text-green-600 font-medium">
                All flats have paid! 🎉
            </div>
          )}
        </div>
       </div>
    </div>
  );
};

export default Reports;
